  COALESCE(SUM(CASE WHEN d.dt>='__DATE_MINUS_6__' AND d.dt<='__BIZ_DATE__' THEN d.cost ELSE CAST(0 AS BIGINT) END),CAST(0 AS BIGINT)) AS cost_7d,
