  COALESCE(SUM(CASE WHEN d.dt<='__BIZ_DATE__' THEN d.ecommerce_pay_order_count ELSE CAST(0 AS BIGINT) END),CAST(0 AS BIGINT)) AS ecommerce_pay_order_count_acc,
  COALESCE(SUM(CASE WHEN d.dt='__BIZ_DATE__' THEN d.ecommerce_refund_order_count ELSE CAST(0 AS BIGINT) END),CAST(0 AS BIGINT)) AS ecommerce_refund_order_count_1d,
  COALESCE(SUM(CASE WHEN d.dt>='__DATE_MINUS_6__' AND d.dt<='__BIZ_DATE__' THEN d.ecommerce_refund_order_count ELSE CAST(0 AS BIGINT) END),CAST(0 AS BIGINT)) AS ecommerce_refund_order_count_7d,
  COALESCE(SUM(CASE WHEN d.dt>='__DATE_MINUS_29__' AND d.dt<='__BIZ_DATE__' THEN d.ecommerce_refund_order_count ELSE CAST(0 AS BIGINT) END),CAST(0 AS BIGINT)) AS ecommerce_refund_order_count_30d,
  COALESCE(SUM(CASE WHEN d.dt<='__BIZ_DATE__' THEN d.ecommerce_refund_order_count ELSE CAST(0 AS BIGINT) END),CAST(0 AS BIGINT)) AS ecommerce_refund_order_count_acc,
  COALESCE(SUM(CASE WHEN d.dt='__BIZ_DATE__' THEN d.ecommerce_pay_order_gmv ELSE CAST(0 AS BIGINT) END),CAST(0 AS BIGINT)) AS ecommerce_pay_order_gmv_1d,
  COALESCE(SUM(CASE WHEN d.dt>='__DATE_MINUS_6__' AND d.dt<='__BIZ_DATE__' THEN d.ecommerce_pay_order_gmv ELSE CAST(0 AS BIGINT) END),CAST(0 AS BIGINT)) AS ecommerce_pay_order_gmv_7d,
  COALESCE(SUM(CASE WHEN d.dt>='__DATE_MINUS_29__' AND d.dt<='__BIZ_DATE__' THEN d.ecommerce_pay_order_gmv ELSE CAST(0 AS BIGINT) END),CAST(0 AS BIGINT)) AS ecommerce_pay_order_gmv_30d,
