  COALESCE(SUM(CASE WHEN d.dt>='__DATE_MINUS_29__' AND d.dt<='__BIZ_DATE__' THEN d.short_video_pay_order_gmv ELSE CAST(0 AS BIGINT) END),CAST(0 AS BIGINT)) AS short_video_pay_order_gmv_30d,
